import{_ as a,c as t,o as i,ag as n}from"./chunks/framework.CB_NIqHd.js";const p=JSON.parse('{"title":"Node.js — Zero to Strong Medior","description":"A structured Node.js backend learning path from runtime foundations to production diagnostics and distributed systems.","frontmatter":{"title":"Node.js — Zero to Strong Medior","description":"A structured Node.js backend learning path from runtime foundations to production diagnostics and distributed systems.","outline":"deep"},"headers":[],"relativePath":"node-js/index.md","filePath":"node-js/index.md"}'),r={name:"node-js/index.md"};function o(s,e,l,d,c,h){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="node-js-zero-to-strong-medior" tabindex="-1">Node.js: Zero to Strong Medior <a class="header-anchor" href="#node-js-zero-to-strong-medior" aria-label="Permalink to “Node.js: Zero to Strong Medior”">​</a></h1><p>This learning path starts with the Node.js runtime and gradually builds toward independent ownership of production backend services.</p><p>The modules explain four sides of each important concept:</p><ul><li><strong>Mechanics:</strong> what the API or pattern does.</li><li><strong>Selection:</strong> when it is appropriate and what the alternatives are.</li><li><strong>Failure modes:</strong> how it breaks and how to diagnose it.</li><li><strong>Production consequences:</strong> how it affects performance, security, reliability, and maintenance.</li></ul><p>The chapters are designed to be read in order. Experienced developers can also use them as standalone references.</p><h2 id="learning-path" tabindex="-1">Learning path <a class="header-anchor" href="#learning-path" aria-label="Permalink to “Learning path”">​</a></h2><h3 id="foundations" tabindex="-1">Foundations <a class="header-anchor" href="#foundations" aria-label="Permalink to “Foundations”">​</a></h3><ol><li><a href="./module-01-nodejs-foundations.html">Node.js Foundations</a> — the runtime, modules, npm, asynchronous JavaScript, and the event loop.</li><li><a href="./module-02-standard-library.html">Node.js Standard Library</a> — processes, files, child processes, clustering, and worker threads.</li><li><a href="./module-03-events-buffers-streams.html">EventEmitter, Buffers, and Streams</a> — events, binary data, streaming, backpressure, cancellation, and cleanup.</li><li><a href="./module-04-testing.html">Testing Node.js Applications</a> — test design, Jest, isolation, integration tests, concurrency, and flaky-test diagnosis.</li></ol><h3 id="building-backend-services" tabindex="-1">Building backend services <a class="header-anchor" href="#building-backend-services" aria-label="Permalink to “Building backend services”">​</a></h3><ol start="5"><li><p><a href="./module-05-networking.html">Networking in Node.js</a> — HTTP, REST, TLS, clients, WebSockets, timeouts, retries, and idempotency.</p><ul><li><a href="./realtime-transports.html">SSE, Bounded Polling and gRPC</a> — replay, heartbeat, slow consumers, cancellation and transport selection.</li></ul></li><li><p><a href="./module-06-express-architecture.html">Express and Layered Architecture</a> — controllers, services, repositories, dependency boundaries, transactions, and request context.</p></li><li><p><a href="./module-07-mongodb-mongoose.html">MongoDB and Mongoose</a> — document modeling, indexes, aggregation, transactions, concurrency, and schema evolution.</p></li><li><p><a href="./module-08-postgresql-mikroorm.html">PostgreSQL and MikroORM</a> — relational modeling, SQL, transactions, locking, migrations, and query diagnosis.</p><ul><li><p><a href="./sql-query-workbench.html">SQL Query Workbench</a> — parameterized CRUD, reporting grain, grouping, subqueries, CTEs and window functions.</p></li><li><p><a href="./cursor-pagination.html">Deterministic Cursor Pagination</a> — scoped signed cursors, microsecond precision and live-feed consistency.</p></li><li><p><a href="./dates-and-time-zones.html">Dates and Time Zones</a> — strict boundaries, calendar versus elapsed arithmetic, DST and Intl.</p></li><li><p><a href="./database-recovery.html">Database Recovery</a> — logical restore, PITR, recovery verification and RPO/RTO.</p></li></ul></li></ol><h3 id="security-and-production-ownership" tabindex="-1">Security and production ownership <a class="header-anchor" href="#security-and-production-ownership" aria-label="Permalink to “Security and production ownership”">​</a></h3><ol start="9"><li><a href="./module-09-authentication-authorization.html">Authentication and Authorization</a> — passwords, sessions, tokens, OAuth/OIDC, permissions, browser security, and application attack surfaces.</li><li><a href="./module-10-production-ready-applications.html">Production-Ready Node.js Applications</a> — configuration, logging, health checks, graceful shutdown, error handling, and API hardening.</li><li><a href="./module-11-performance-diagnostics.html">Performance and Diagnostics</a> — latency, saturation, event-loop health, memory, profiling, database pools, and load testing.</li><li><a href="./module-12-resilient-distributed-systems.html">Resilient Architecture and Distributed Systems</a> — messaging, idempotency, retries, outbox workflows, sagas, caching, circuit breakers, and distributed consistency.</li></ol><h2 id="worked-boundary-labs-and-alternatives" tabindex="-1">Worked boundary labs and alternatives <a class="header-anchor" href="#worked-boundary-labs-and-alternatives" aria-label="Permalink to “Worked boundary labs and alternatives”">​</a></h2><p>These complement the primary modules; links are navigation, not additional completion evidence.</p><ul><li><a href="./full-stack-deployment.html">Full-stack deployment and recovery</a> — executed local HTTPS frontend/API/database, restore/rollback, hosted runbook and Kubernetes awareness.</li><li><a href="./signed-webhooks.html">Signed webhooks</a> — raw bytes, timestamp windows, rotating keys and durable duplicate handling.</li><li><a href="./jobs-and-schedules.html">Durable jobs and schedules</a> — real RabbitMQ acknowledgements/retries/dead letters and PostgreSQL overlap/checkpoint behavior.</li><li><a href="./rest-contract-workbench.html">REST contract workbench</a> — generated OpenAPI/runtime schemas with actual endpoint/error/permission and drift checks.</li><li><a href="./graphql-basics.html">GraphQL catalogue</a> — a bounded alternative API with actual schema/query/authorization-scope and batched-loading checks; REST remains primary.</li><li><a href="./release-artifact-compatibility.html">Release artifact compatibility</a> — exact package identities and real PostgreSQL expand/contract/rollback boundaries.</li><li><a href="./container-deployment-lab.html">Container deployment lab</a> — actual image/Compose/database/readiness/shutdown/persistence checks.</li><li><a href="./aws-service-slice.html">AWS service slice</a> — scoped infrastructure/IAM/cost-model material with static validation, not a claimed cloud deployment.</li><li><a href="./../senior_growth/EngX_Quality/Large_Data_Workflow.html">React query ownership</a> — the frontend counterpart to complete-body deadlines and stale-response protection.</li></ul><p>Use PostgreSQL/MikroORM as the primary relational path; MongoDB, GraphQL and other tools are alternatives to compare when the requirement justifies them. Keep Autocode&#39;s supplied build/Jest scripts, database settings and restricted test directory unchanged. Only the user may push repository changes.</p><h2 id="how-to-study" tabindex="-1">How to study <a class="header-anchor" href="#how-to-study" aria-label="Permalink to “How to study”">​</a></h2><p>For each chapter:</p><ol><li>Read the concept and restate it in your own words.</li><li>Run or rewrite the small examples.</li><li>Complete the failure-driven exercises without copying the suggested approach.</li><li>Explain why your solution is appropriate and when you would choose another design.</li><li>Return to the final checklist and identify anything you cannot yet explain clearly.</li></ol><p>Reading creates recognition. Independent implementation, failure diagnosis and defended design decisions require separate practice/evidence; completed learning material does not establish professional readiness.</p>',20)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
